package com.jian.scrcpy.record;
import com.jian.scrcpy.protocol.*;import io.netty.buffer.ByteBuf;import org.bytedeco.ffmpeg.avcodec.*;import org.bytedeco.ffmpeg.avformat.*;import org.bytedeco.ffmpeg.avutil.*;import org.bytedeco.javacpp.*;import java.nio.file.Path;import java.util.concurrent.*;
import static org.bytedeco.ffmpeg.global.avcodec.*;import static org.bytedeco.ffmpeg.global.avformat.*;import static org.bytedeco.ffmpeg.global.avutil.*;
public final class PacketRecorder implements AutoCloseable{
 public record EncodedPacket(boolean video,CodecId codec,long pts,boolean config,boolean key,byte[] data){}
 private final BlockingQueue<EncodedPacket> queue=new LinkedBlockingQueue<>(512);private final Path file;private final String format;private volatile boolean running;private Thread thread;private AVFormatContext ctx;private AVStream video,audio;private long origin=Long.MIN_VALUE,lastV=Long.MIN_VALUE,lastA=Long.MIN_VALUE;
 public PacketRecorder(Path file){this.file=file;String n=file.getFileName().toString().toLowerCase();format=n.endsWith(".mkv")?"matroska":"mp4";}
 public boolean offer(boolean isVideo,CodecId codec,MediaMessage.Packet p){ByteBuf b=p.data();byte[] d=new byte[b.readableBytes()];b.getBytes(b.readerIndex(),d);return queue.offer(new EncodedPacket(isVideo,codec,p.pts(),p.config(),p.keyFrame(),d));}
 public synchronized void start(){if(running)return;running=true;thread=Thread.ofPlatform().name("scrcpy-recorder").start(this::run);}
 private static int avCodec(CodecId c){return switch(c){case H264->AV_CODEC_ID_H264;case H265->AV_CODEC_ID_HEVC;case AV1->AV_CODEC_ID_AV1;case OPUS->AV_CODEC_ID_OPUS;case AAC->AV_CODEC_ID_AAC;case FLAC->AV_CODEC_ID_FLAC;default->AV_CODEC_ID_NONE;};}
 private AVStream stream(EncodedPacket p){AVStream s=p.video?video:audio;if(s!=null)return s;s=avformat_new_stream(ctx,(AVCodec)null);s.time_base(new AVRational().num(1).den(1_000_000));s.codecpar().codec_type(p.video?AVMEDIA_TYPE_VIDEO:AVMEDIA_TYPE_AUDIO).codec_id(avCodec(p.codec));if(p.video)video=s;else audio=s;return s;}
 private void config(AVStream s,byte[] data){BytePointer x=new BytePointer(av_malloc(data.length+AV_INPUT_BUFFER_PADDING_SIZE));x.put(data);s.codecpar().extradata(x).extradata_size(data.length);}
 private void write(EncodedPacket p){AVStream s=stream(p);if(p.config){config(s,p.data);return;}if(origin==Long.MIN_VALUE)origin=p.pts;long pts=p.pts-origin;long last=p.video?lastV:lastA;if(last!=Long.MIN_VALUE&&pts<=last)pts=last+1;if(p.video)lastV=pts;else lastA=pts;AVPacket pkt=av_packet_alloc();try(BytePointer data=new BytePointer(p.data)){pkt.data(data).size(p.data.length).stream_index(s.index()).pts(pts).dts(pts);if(p.key)pkt.flags(pkt.flags()|AV_PKT_FLAG_KEY);av_packet_rescale_ts(pkt,new AVRational().num(1).den(1_000_000),s.time_base());if(av_interleaved_write_frame(ctx,pkt)<0)throw new IllegalStateException("mux write failed");}finally{av_packet_free(pkt);}}
 private void open(){ctx=avformat_alloc_context();AVOutputFormat of=av_guess_format(format,null,null);if(of==null)throw new IllegalStateException("muxer unavailable: "+format);ctx.oformat(of);if(avio_open(ctx.pb(),file.toAbsolutePath().toString(),AVIO_FLAG_WRITE)<0)throw new IllegalStateException("cannot open "+file);}
 private void run(){boolean header=false;try{open();while(running||!queue.isEmpty()){EncodedPacket p=queue.poll(100,TimeUnit.MILLISECONDS);if(p==null)continue;AVStream s=stream(p);if(p.config){config(s,p.data);continue;}if(!header){if(avformat_write_header(ctx,(AVDictionary)null)<0)throw new IllegalStateException("cannot write header");header=true;}write(p);}if(header)av_write_trailer(ctx);}catch(Exception e){throw new RuntimeException(e);}finally{if(ctx!=null){if(ctx.pb()!=null)avio_closep(ctx.pb());avformat_free_context(ctx);ctx=null;}}}
 public synchronized void close(){running=false;if(thread!=null)try{thread.join(5000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}